export default [{"w":"activism","pos":"noun","def":"The practice of taking direct action to bring about political or social change.","defId":"Aktivisme; praktik memperjuangkan perubahan politik atau sosial secara langsung.","ex":"Her online activism helped raise awareness of climate issues.","exId":"Aktivisme daringnya membantu meningkatkan kesadaran akan isu iklim.","colloc":["political activism","grassroots activism"],"theme":"society"},{"w":"affluence","pos":"noun","def":"The state of having a great deal of money and a comfortable standard of living.","defId":"Kemakmuran; keadaan memiliki banyak uang dan taraf hidup yang tinggi.","ex":"The suburb's affluence is obvious from its large houses and expensive cars.","exId":"Kemakmuran daerah pinggiran itu terlihat jelas dari rumah-rumah besar dan mobil mahalnya.","colloc":["growing affluence","sign of affluence"],"theme":"society"},{"w":"ageing population","pos":"noun","def":"A population in which the average age is rising because people live longer and fewer children are born.","defId":"Populasi menua; populasi dengan proporsi orang lanjut usia yang semakin meningkat.","ex":"An ageing population is putting increasing pressure on the health service.","exId":"Populasi yang menua memberikan tekanan yang semakin besar pada layanan kesehatan.","colloc":["rapidly ageing population","cope with an ageing population"],"theme":"society"},{"w":"alienation","pos":"noun","def":"A feeling of being isolated or estranged from society, work, or other people.","defId":"Keterasingan; perasaan terisolasi atau terpisah dari masyarakat atau orang lain.","ex":"Long hours and low pay led to a deep sense of alienation among workers.","exId":"Jam kerja panjang dan upah rendah menimbulkan rasa keterasingan yang mendalam di kalangan pekerja.","colloc":["social alienation","sense of alienation"],"theme":"society"},{"w":"assimilation","pos":"noun","def":"the process by which a person or group becomes part of a different culture","defId":"proses ketika seseorang atau kelompok menjadi bagian dari budaya yang berbeda","ex":"The assimilation of newcomers is easier when local people are welcoming.","exId":"Asimilasi pendatang baru menjadi lebih mudah ketika penduduk setempat bersikap ramah.","colloc":["cultural assimilation","process of assimilation","forced assimilation"],"theme":"society"},{"w":"asylum seeker","pos":"noun","def":"a person who has left their country and is seeking protection in another","defId":"pencari suaka; orang yang meninggalkan negaranya dan mencari perlindungan di negara lain","ex":"The charity provides legal advice to asylum seekers awaiting a decision.","exId":"Lembaga amal itu memberi nasihat hukum kepada pencari suaka yang menunggu keputusan.","colloc":["destitute asylum seeker","support asylum seekers","asylum seeker application"],"theme":"society"},{"w":"belonging","pos":"noun","def":"the feeling of being accepted as a member of a group or place","defId":"rasa memiliki; perasaan diterima sebagai bagian dari suatu kelompok atau tempat","ex":"Community events give isolated residents a much-needed sense of belonging.","exId":"Acara komunitas memberi penghuni yang terisolasi rasa memiliki yang sangat dibutuhkan.","colloc":["sense of belonging","feeling of belonging","foster belonging"],"theme":"society"},{"w":"bias","pos":"noun","def":"an unfair preference for or against a person or group","defId":"kecenderungan tidak adil yang mendukung atau menentang seseorang atau kelompok","ex":"The report found evidence of racial bias in the hiring process.","exId":"Laporan itu menemukan bukti adanya bias rasial dalam proses perekrutan.","colloc":["racial bias","gender bias","unconscious bias"],"theme":"society"},{"w":"bigotry","pos":"noun","def":"Intolerance and prejudice towards people who hold different opinions or come from different backgrounds.","defId":"Kefanatikan; ketidaktoleranan dan prasangka terhadap orang yang berbeda.","ex":"The campaign aimed to challenge bigotry and promote understanding.","exId":"Kampanye itu bertujuan menantang kefanatikan dan mendorong saling pengertian.","colloc":["racial bigotry","confront bigotry"],"theme":"society"},{"w":"birth rate","pos":"noun","def":"The number of live births in a population, usually measured per thousand people each year.","defId":"Angka kelahiran; jumlah kelahiran per seribu penduduk setiap tahun.","ex":"The country's falling birth rate has alarmed policymakers.","exId":"Angka kelahiran negara itu yang terus menurun mengkhawatirkan para pembuat kebijakan.","colloc":["falling birth rate","declining birth rate"],"theme":"society"},{"w":"boycott","pos":"noun, verb","def":"A refusal to buy, use, or take part in something as a form of protest.","defId":"Boikot; penolakan membeli atau ikut serta dalam sesuatu sebagai bentuk protes.","ex":"Consumers organised a boycott of the company over its labour practices.","exId":"Para konsumen mengorganisir boikot terhadap perusahaan itu atas praktik ketenagakerjaannya.","colloc":["consumer boycott","call for a boycott"],"theme":"society"},{"w":"breadline","pos":"noun","def":"The level of extreme poverty at which people have only just enough to survive.","defId":"Garis kemiskinan; tingkat pendapatan yang hanya cukup untuk bertahan hidup.","ex":"Rising rents have pushed many families onto the breadline.","exId":"Kenaikan sewa telah mendorong banyak keluarga ke garis kemiskinan.","colloc":["on the breadline","below the breadline"],"theme":"society"},{"w":"bystander","pos":"noun","def":"a person who is present at an event but does not take part in it","defId":"orang yang menyaksikan; orang yang hadir pada suatu peristiwa tetapi tidak ikut terlibat","ex":"An innocent bystander stepped in to help the injured cyclist.","exId":"Seorang penonton tak bersalah turun tangan menolong pesepeda yang terluka.","colloc":["innocent bystander","a passive bystander","bystander effect"],"theme":"society"},{"w":"caste","pos":"noun","def":"a fixed social class into which a person is born and cannot easily leave","defId":"kasta; kelas sosial tetap tempat seseorang dilahirkan dan sulit ditinggalkan","ex":"Reformers campaigned for decades to dismantle discrimination based on caste.","exId":"Para pembaru berkampanye selama puluhan tahun untuk membongkar diskriminasi berdasarkan kasta.","colloc":["caste system","lower caste","caste discrimination"],"theme":"society"},{"w":"census","pos":"noun","def":"an official count and survey of a population and its characteristics","defId":"sensus; pencacahan dan survei resmi atas jumlah penduduk beserta karakteristiknya","ex":"The latest census revealed a sharp rise in single-person households.","exId":"Sensus terbaru mengungkap lonjakan tajam rumah tangga satu orang.","colloc":["national census","conduct a census","census data"],"theme":"society"},{"w":"charitable","pos":"adjective","def":"relating to or characterised by the giving of help to those in need","defId":"amal; berkaitan dengan atau bersifat memberi bantuan kepada yang membutuhkan","ex":"The company donates a share of its profits to charitable causes each year.","exId":"Perusahaan itu menyumbangkan sebagian labanya untuk kegiatan amal setiap tahun.","colloc":["charitable donation","charitable cause","charitable organisation"],"theme":"society"},{"w":"citizenry","pos":"noun","def":"all the citizens of a place regarded collectively","defId":"warga negara secara keseluruhan; segenap penduduk suatu tempat","ex":"An informed citizenry is essential to the healthy functioning of any democracy.","exId":"Warga negara yang terinformasi sangat penting bagi berjalannya demokrasi yang sehat.","colloc":["informed citizenry","engaged citizenry","the wider citizenry"],"theme":"society"},{"w":"citizenship","pos":"noun","def":"the legal right to belong to a particular country","defId":"hak hukum untuk menjadi bagian dari suatu negara tertentu","ex":"After living there for ten years, she applied for citizenship.","exId":"Setelah tinggal di sana selama sepuluh tahun, dia mengajukan permohonan kewarganegaraan.","colloc":["apply for citizenship","dual citizenship","grant citizenship"],"theme":"society"},{"w":"civic","pos":"adjective","def":"relating to a city or town and the people who live there, or to being a citizen","defId":"berkaitan dengan kota dan penduduknya, atau dengan menjadi warga negara","ex":"Voting in elections is an important civic duty for every citizen.","exId":"Memberikan suara dalam pemilu merupakan kewajiban warga negara yang penting bagi setiap warga.","colloc":["civic duty","civic pride","civic engagement"],"theme":"society"},{"w":"civic duty","pos":"noun","def":"a responsibility that citizens are expected to fulfil for the good of society","defId":"kewajiban sipil; tanggung jawab yang diharapkan dipenuhi warga demi kebaikan masyarakat","ex":"Many people regard voting not merely as a right but as a civic duty.","exId":"Banyak orang menganggap memilih bukan sekadar hak melainkan kewajiban sipil.","colloc":["fulfil a civic duty","sense of civic duty","perform your civic duty"],"theme":"society"},{"w":"civil","pos":"adjective","def":"relating to the ordinary citizens of a country and their rights, rather than to crime or the military","defId":"berkaitan dengan warga negara biasa dan hak-hak mereka, bukan dengan kejahatan atau militer","ex":"The movement fought for the civil rights of every citizen, regardless of race.","exId":"Gerakan itu memperjuangkan hak-hak sipil setiap warga negara, tanpa memandang ras.","colloc":["civil rights","civil society","civil liberties"],"theme":"society"},{"w":"civil society","pos":"noun","def":"The organisations and citizens that operate independently of government and business to serve common interests.","defId":"Masyarakat sipil; komunitas warga dan organisasi di luar pemerintah dan bisnis.","ex":"A strong civil society is essential for holding governments accountable.","exId":"Masyarakat sipil yang kuat sangat penting untuk menuntut pertanggungjawaban pemerintah.","colloc":["vibrant civil society","civil society organisations"],"theme":"society"},{"w":"clan","pos":"noun","def":"a large group of families descended from a common ancestor, often bound by loyalty","defId":"klan; kelompok besar keluarga yang berasal dari satu leluhur dan terikat kesetiaan","ex":"In the highlands, each clan traditionally controlled its own valley and grazing land.","exId":"Di dataran tinggi, setiap klan secara tradisional menguasai lembah dan padang gembalaannya sendiri.","colloc":["rival clans","a powerful clan","clan loyalty"],"theme":"society"},{"w":"class divide","pos":"noun","def":"The division and inequality that exists between different social classes in a society.","defId":"Kesenjangan kelas; jurang pemisah antara kelas sosial yang berbeda.","ex":"The widening class divide has left poorer families struggling to keep up.","exId":"Kesenjangan kelas yang semakin lebar membuat keluarga miskin kesulitan mengejar ketertinggalan.","colloc":["widening class divide","bridge the class divide"],"theme":"society"},{"w":"coexistence","pos":"noun","def":"the state of living together peacefully despite differences","defId":"koeksistensi; keadaan hidup berdampingan secara damai meski ada perbedaan","ex":"Decades of peaceful coexistence between the two communities are a source of pride.","exId":"Puluhan tahun koeksistensi damai antara kedua komunitas menjadi sumber kebanggaan.","colloc":["peaceful coexistence","harmonious coexistence","coexistence between groups"],"theme":"society"},{"w":"cohesion","pos":"noun","def":"the state of being united and working well together as a group","defId":"keadaan bersatu dan bekerja sama dengan baik sebagai suatu kelompok","ex":"Community events can strengthen social cohesion in diverse neighbourhoods.","exId":"Acara komunitas dapat memperkuat kohesi sosial di lingkungan yang beragam.","colloc":["social cohesion","community cohesion","strengthen cohesion"],"theme":"society"},{"w":"cohesive","pos":"adjective","def":"united and working well together as a whole","defId":"kohesif; bersatu dan berfungsi baik sebagai satu kesatuan","ex":"Shared festivals help keep the village a cohesive and supportive community.","exId":"Perayaan bersama membantu menjaga desa itu tetap sebagai komunitas yang kohesif dan saling mendukung.","colloc":["socially cohesive","a cohesive society","cohesive community"],"theme":"society"},{"w":"common good","pos":"noun","def":"the benefit or interests of the community as a whole","defId":"kebaikan bersama; manfaat atau kepentingan masyarakat secara keseluruhan","ex":"They called on residents to set aside private gain and act for the common good.","exId":"Mereka menyeru warga mengesampingkan keuntungan pribadi dan bertindak demi kebaikan bersama.","colloc":["serve the common good","for the common good","promote the common good"],"theme":"society"},{"w":"communal","pos":"adjective","def":"shared by or belonging to all members of a community","defId":"komunal; dimiliki atau digunakan bersama oleh seluruh anggota komunitas","ex":"Residents of the block share a communal garden and a laundry room.","exId":"Penghuni blok itu berbagi taman komunal dan ruang cuci bersama.","colloc":["communal spaces","communal living","communal facilities"],"theme":"society"},{"w":"community spirit","pos":"noun","def":"A sense of belonging and willingness to help among people living in the same community.","defId":"Semangat kebersamaan; rasa memiliki dan kerja sama antar warga dalam suatu komunitas.","ex":"The street party brought back a real sense of community spirit.","exId":"Pesta jalanan itu menghidupkan kembali semangat kebersamaan yang sesungguhnya.","colloc":["strong community spirit","foster community spirit"],"theme":"society"},{"w":"conformity","pos":"noun","def":"behaviour that follows the usual rules or expectations of a group or society","defId":"perilaku yang mengikuti aturan atau harapan yang lazim dari suatu kelompok atau masyarakat","ex":"There is strong social pressure towards conformity in some communities.","exId":"Ada tekanan sosial yang kuat menuju konformitas di sebagian komunitas.","colloc":["social conformity","cultural conformity","conformity to norms"],"theme":"society"},{"w":"counterculture","pos":"noun","def":"a way of life and set of values that opposes the accepted norms of mainstream society","defId":"budaya tandingan; cara hidup dan nilai-nilai yang menentang norma umum masyarakat arus utama","ex":"The music of the era gave voice to a counterculture that rejected consumerism.","exId":"Musik pada era itu menyuarakan budaya tandingan yang menolak konsumerisme.","colloc":["youth counterculture","emerging counterculture","counterculture movement"],"theme":"society"},{"w":"custody","pos":"noun","def":"the state of being held by the police or kept in prison","defId":"keadaan ditahan oleh polisi atau dipenjara","ex":"The suspect was taken into custody shortly after the robbery.","exId":"Tersangka ditahan tak lama setelah perampokan itu.","colloc":["take into custody","in police custody","remand in custody"],"theme":"society"},{"w":"demographic","pos":"adjective","def":"relating to the population and the different groups within it","defId":"berkaitan dengan populasi dan kelompok-kelompok berbeda di dalamnya","ex":"Demographic changes, such as an ageing population, affect the demand for healthcare.","exId":"Perubahan demografis, seperti populasi yang menua, memengaruhi permintaan akan layanan kesehatan.","colloc":["demographic change","demographic trends","demographic shift"],"theme":"society"},{"w":"demonstration","pos":"noun","def":"A public gathering of people to protest against something or show support for a cause.","defId":"Demonstrasi; pertemuan publik untuk memprotes atau mendukung suatu tujuan.","ex":"A peaceful demonstration was held outside parliament to demand reform.","exId":"Demonstrasi damai digelar di luar gedung parlemen untuk menuntut reformasi.","colloc":["peaceful demonstration","hold a demonstration"],"theme":"society"},{"w":"denizen","pos":"noun","def":"a person, animal or plant that lives or is often found in a particular place","defId":"penghuni; orang, hewan, atau tumbuhan yang menetap atau sering ditemukan di suatu tempat","ex":"As a long-time denizen of the old quarter, she knew every shopkeeper by name.","exId":"Sebagai penghuni lama kawasan tua itu, dia mengenal setiap pemilik toko dengan nama.","colloc":["a denizen of the city","local denizens","denizen of the forest"],"theme":"society"},{"w":"deportation","pos":"noun","def":"the official removal of a foreign national from a country","defId":"deportasi; pengusiran resmi seorang warga asing dari suatu negara","ex":"The family launched an appeal to avoid deportation.","exId":"Keluarga itu mengajukan banding untuk menghindari deportasi.","colloc":["face deportation","threat of deportation","deportation order"],"theme":"society"},{"w":"deprivation","pos":"noun","def":"the lack of the basic things that people need for a good life, such as food and housing","defId":"kekurangan hal-hal dasar yang dibutuhkan orang untuk hidup layak, seperti makanan dan tempat tinggal","ex":"Children growing up in areas of deprivation often have fewer opportunities.","exId":"Anak-anak yang tumbuh di daerah yang serba kekurangan sering kali memiliki lebih sedikit kesempatan.","colloc":["social deprivation","areas of deprivation","material deprivation"],"theme":"society"},{"w":"destitution","pos":"noun","def":"The state of extreme poverty in which a person lacks the basic necessities of life.","defId":"Kemelaratan; kondisi kemiskinan ekstrem tanpa kebutuhan dasar hidup.","ex":"Losing his job pushed the family to the edge of destitution.","exId":"Kehilangan pekerjaan mendorong keluarga itu ke ambang kemelaratan.","colloc":["utter destitution","face destitution"],"theme":"society"},{"w":"deterrent","pos":"noun","def":"something that makes people less likely to do something, especially commit a crime","defId":"sesuatu yang membuat orang cenderung tidak melakukan sesuatu, terutama melakukan kejahatan","ex":"Many believe that longer prison sentences act as a deterrent to crime.","exId":"Banyak orang percaya bahwa hukuman penjara yang lebih lama berfungsi sebagai pencegah kejahatan.","colloc":["act as a deterrent","strong deterrent","deterrent effect"],"theme":"society"},{"w":"deviance","pos":"noun","def":"Behaviour that differs from what society considers normal or acceptable.","defId":"Penyimpangan; perilaku yang menyimpang dari norma sosial yang berlaku.","ex":"Sociologists study deviance to understand how societies define right and wrong.","exId":"Para sosiolog mempelajari penyimpangan untuk memahami bagaimana masyarakat mendefinisikan benar dan salah.","colloc":["social deviance","acts of deviance"],"theme":"society"},{"w":"disadvantage","pos":"noun","def":"An unfavourable condition or situation that puts a person or group at a lower position than others.","defId":"Kerugian; keadaan tidak menguntungkan yang menempatkan seseorang pada posisi lebih rendah.","ex":"Children from poorer areas often start school at a serious disadvantage.","exId":"Anak-anak dari daerah miskin sering memulai sekolah dengan kerugian yang serius.","colloc":["social disadvantage","economic disadvantage"],"theme":"society"},{"w":"discrimination","pos":"noun","def":"the unfair treatment of people because of their race, gender, age, or other differences","defId":"perlakuan tidak adil terhadap orang karena ras, jenis kelamin, usia, atau perbedaan lainnya","ex":"The law bans discrimination against employees on the basis of their gender.","exId":"Undang-undang itu melarang diskriminasi terhadap karyawan berdasarkan jenis kelamin mereka.","colloc":["racial discrimination","age discrimination","face discrimination"],"theme":"society"},{"w":"disenfranchise","pos":"verb","def":"To deprive someone of a right or privilege, especially the right to vote.","defId":"Mencabut hak; menghilangkan hak seseorang, terutama hak untuk memilih.","ex":"Strict identity laws could disenfranchise thousands of poorer voters.","exId":"Undang-undang identitas yang ketat dapat mencabut hak ribuan pemilih miskin.","colloc":["disenfranchise voters","politically disenfranchise"],"theme":"society"},{"w":"dissident","pos":"noun","def":"a person who publicly opposes the policies of the government or an established authority","defId":"pembangkang; orang yang secara terbuka menentang kebijakan pemerintah atau otoritas mapan","ex":"The exiled dissident continued to write critical essays about the regime.","exId":"Pembangkang yang diasingkan itu terus menulis esai kritis tentang rezim.","colloc":["political dissident","exiled dissident","dissident voices"],"theme":"society"},{"w":"diversity","pos":"noun","def":"the fact of including many different types of people or things","defId":"keadaan yang mencakup banyak jenis orang atau hal yang berbeda","ex":"The city celebrates its cultural diversity with festivals from many different communities.","exId":"Kota ini merayakan keberagaman budayanya dengan festival dari berbagai komunitas.","colloc":["cultural diversity","ethnic diversity","celebrate diversity"],"theme":"society"},{"w":"downtrodden","pos":"adjective","def":"Oppressed and badly treated by people with more power or wealth.","defId":"Tertindas; diperlakukan buruk oleh mereka yang lebih berkuasa.","ex":"The party claimed to speak for the downtrodden and the poor.","exId":"Partai itu mengaku menyuarakan kaum tertindas dan kaum miskin.","colloc":["downtrodden masses","downtrodden workers"],"theme":"society"},{"w":"egalitarian","pos":"adjective","def":"Believing in or based on the principle that all people are equal and deserve equal rights.","defId":"Egaliter; meyakini bahwa semua orang setara dan berhak atas hak yang sama.","ex":"They dreamed of building a more egalitarian society without class divisions.","exId":"Mereka bermimpi membangun masyarakat yang lebih egaliter tanpa pembagian kelas.","colloc":["egalitarian society","egalitarian values"],"theme":"society"},{"w":"elite","pos":"noun","def":"A small group of people who hold the most power, wealth, or influence in society.","defId":"Elite; kelompok kecil yang memiliki kekuasaan, kekayaan, atau pengaruh terbesar.","ex":"A tiny elite controls most of the country's land and resources.","exId":"Segelintir elite menguasai sebagian besar tanah dan sumber daya negara itu.","colloc":["ruling elite","political elite"],"theme":"society"},{"w":"empowerment","pos":"noun","def":"The process of giving people the confidence, power, or authority to control their own lives.","defId":"Pemberdayaan; proses memberi orang kendali dan kekuatan atas hidup mereka.","ex":"Microloans are often praised for the economic empowerment of women.","exId":"Pinjaman mikro sering dipuji atas pemberdayaan ekonomi perempuan.","colloc":["women's empowerment","economic empowerment"],"theme":"society"},{"w":"enclave","pos":"noun","def":"a distinct area whose inhabitants differ culturally or socially from those around them","defId":"enklaf; kawasan tersendiri yang penghuninya berbeda budaya atau sosial dari sekitarnya","ex":"The district became an enclave for artists priced out of the city centre.","exId":"Distrik itu menjadi enklaf bagi para seniman yang tersingkir dari pusat kota karena harga.","colloc":["ethnic enclave","a wealthy enclave","cultural enclave"],"theme":"society"},{"w":"entrenched","pos":"adjective","def":"firmly established and very difficult to change","defId":"mengakar; tertanam kuat dan sangat sulit diubah","ex":"Deeply entrenched attitudes about gender roles change slowly.","exId":"Sikap yang mengakar tentang peran gender berubah dengan lambat.","colloc":["deeply entrenched","entrenched inequality","become entrenched"],"theme":"society"},{"w":"equity","pos":"noun","def":"The quality of being fair and impartial, ensuring people are treated justly.","defId":"Keadilan; sifat adil dan tidak memihak dalam memperlakukan orang.","ex":"Campaigners are calling for greater equity in access to healthcare.","exId":"Para pegiat menyerukan keadilan yang lebih besar dalam akses ke layanan kesehatan.","colloc":["social equity","equity and fairness"],"theme":"society"},{"w":"ethnicity","pos":"noun","def":"the fact of belonging to a particular race or cultural group","defId":"keadaan menjadi bagian dari suatu ras atau kelompok budaya tertentu","ex":"The survey collected data on people's age, gender, and ethnicity.","exId":"Survei itu mengumpulkan data tentang usia, jenis kelamin, dan etnisitas orang.","colloc":["different ethnicity","race and ethnicity","mixed ethnicity"],"theme":"society"},{"w":"exclusion","pos":"noun","def":"The act of deliberately preventing someone from taking part in a group, activity, or society.","defId":"Pengucilan; tindakan mencegah seseorang ikut serta dalam kelompok atau masyarakat.","ex":"Poverty can lead to the social exclusion of entire communities.","exId":"Kemiskinan dapat menyebabkan pengucilan sosial terhadap seluruh komunitas.","colloc":["social exclusion","financial exclusion"],"theme":"society"},{"w":"feminism","pos":"noun","def":"The belief in and movement for the social, political, and economic equality of the sexes.","defId":"Feminisme; gerakan dan keyakinan akan kesetaraan hak antara perempuan dan laki-laki.","ex":"Modern feminism campaigns for equal pay and an end to discrimination.","exId":"Feminisme modern memperjuangkan kesetaraan upah dan penghapusan diskriminasi.","colloc":["wave of feminism","modern feminism"],"theme":"society"},{"w":"fragmented","pos":"adjective","def":"broken up into separate parts that no longer work together well","defId":"terfragmentasi; terpecah menjadi bagian-bagian terpisah yang tak lagi menyatu","ex":"Long working hours have left many families feeling increasingly fragmented.","exId":"Jam kerja yang panjang membuat banyak keluarga merasa semakin terfragmentasi.","colloc":["increasingly fragmented","a fragmented society","fragmented community"],"theme":"society"},{"w":"fraternity","pos":"noun","def":"a feeling of friendship and mutual support within a group of people","defId":"persaudaraan; rasa persahabatan dan saling mendukung dalam suatu kelompok","ex":"A strong sense of fraternity binds the members of the fishing community together.","exId":"Rasa persaudaraan yang kuat mengikat para anggota komunitas nelayan itu.","colloc":["sense of fraternity","spirit of fraternity","the medical fraternity"],"theme":"society"},{"w":"gender equality","pos":"noun","def":"The state in which people of all genders have equal rights, opportunities, and treatment.","defId":"Kesetaraan gender; keadaan di mana semua gender memiliki hak dan peluang yang sama.","ex":"The company introduced new policies to promote gender equality at work.","exId":"Perusahaan itu memperkenalkan kebijakan baru untuk mendorong kesetaraan gender di tempat kerja.","colloc":["promote gender equality","gender equality in the workplace"],"theme":"society"},{"w":"generation gap","pos":"noun","def":"The difference in attitudes and values between people of different generations.","defId":"Kesenjangan generasi; perbedaan sikap dan nilai antara generasi yang berbeda.","ex":"The generation gap often shows up in attitudes towards technology.","exId":"Kesenjangan generasi sering terlihat dalam sikap terhadap teknologi.","colloc":["bridge the generation gap","widening generation gap"],"theme":"society"},{"w":"generational","pos":"adjective","def":"relating to or affecting a particular generation, or differences between generations","defId":"terkait generasi; berkaitan dengan atau memengaruhi generasi tertentu maupun perbedaan antargenerasi","ex":"Attitudes towards home ownership reveal a sharp generational divide.","exId":"Sikap terhadap kepemilikan rumah menunjukkan jurang antargenerasi yang tajam.","colloc":["generational divide","generational change","generational shift"],"theme":"society"},{"w":"glass ceiling","pos":"noun","def":"An unofficial barrier that prevents women or minorities from reaching top positions.","defId":"Langit-langit kaca; penghalang tak kasat mata yang mencegah kelompok tertentu naik jabatan.","ex":"Despite her talent, she felt she had hit a glass ceiling at work.","exId":"Meski berbakat, ia merasa telah membentur langit-langit kaca di tempat kerja.","colloc":["break the glass ceiling","hit a glass ceiling"],"theme":"society"},{"w":"hardship","pos":"noun","def":"Suffering or difficulty, especially that caused by a lack of money or basic necessities.","defId":"Kesulitan; penderitaan akibat kekurangan uang atau kebutuhan pokok.","ex":"Many pensioners face real financial hardship during the winter months.","exId":"Banyak pensiunan menghadapi kesulitan keuangan yang nyata selama bulan-bulan musim dingin.","colloc":["financial hardship","endure hardship"],"theme":"society"},{"w":"heritage","pos":"noun","def":"the traditions, buildings, and culture that a society has had for many years","defId":"tradisi, bangunan, dan budaya yang telah dimiliki suatu masyarakat selama bertahun-tahun","ex":"The old temple is an important part of the country's cultural heritage.","exId":"Kuil tua itu merupakan bagian penting dari warisan budaya negara tersebut.","colloc":["cultural heritage","national heritage","heritage site"],"theme":"society"},{"w":"impoverished","pos":"adjective","def":"Made very poor; lacking money and material resources.","defId":"Miskin; menjadi sangat miskin dan kekurangan sumber daya.","ex":"Aid workers struggled to reach the most impoverished villages.","exId":"Para pekerja bantuan kesulitan menjangkau desa-desa yang paling miskin.","colloc":["impoverished communities","impoverished neighbourhood"],"theme":"society"},{"w":"inclusion","pos":"noun","def":"The practice of ensuring that people who might be left out are included and valued.","defId":"Inklusi; praktik memastikan orang yang mungkin terpinggirkan tetap dilibatkan dan dihargai.","ex":"The school has a strong policy of inclusion for children with disabilities.","exId":"Sekolah itu memiliki kebijakan inklusi yang kuat untuk anak-anak penyandang disabilitas.","colloc":["social inclusion","diversity and inclusion"],"theme":"society"},{"w":"inclusivity","pos":"noun","def":"the practice of ensuring that all kinds of people feel welcomed and valued","defId":"inklusivitas; upaya memastikan semua kalangan merasa diterima dan dihargai","ex":"The school promotes inclusivity by celebrating the many cultures of its pupils.","exId":"Sekolah itu mendorong inklusivitas dengan merayakan beragam budaya murid-muridnya.","colloc":["promote inclusivity","greater inclusivity","a culture of inclusivity"],"theme":"society"},{"w":"indigenous","pos":"adjective","def":"belonging to a place because your people have lived there since the earliest times","defId":"berasal dari suatu tempat karena bangsa Anda telah tinggal di sana sejak zaman dahulu","ex":"The government promised to protect the land rights of indigenous peoples.","exId":"Pemerintah berjanji untuk melindungi hak atas tanah masyarakat adat.","colloc":["indigenous people","indigenous communities","indigenous culture"],"theme":"society"},{"w":"inequality","pos":"noun","def":"an unfair situation in which some people have more money, rights, or opportunities than others","defId":"keadaan tidak adil di mana sebagian orang memiliki lebih banyak uang, hak, atau kesempatan daripada yang lain","ex":"The government introduced new policies to reduce income inequality between the rich and the poor.","exId":"Pemerintah memperkenalkan kebijakan baru untuk mengurangi ketimpangan pendapatan antara orang kaya dan orang miskin.","colloc":["income inequality","social inequality","reduce inequality"],"theme":"society"},{"w":"inequity","pos":"noun","def":"a situation of unfairness in the way people are treated or resources are shared","defId":"ketidakadilan; kondisi tidak adil dalam perlakuan terhadap orang atau pembagian sumber daya","ex":"Campaigners highlighted the glaring inequity in access to healthcare.","exId":"Para pegiat menyoroti ketidakadilan mencolok dalam akses layanan kesehatan.","colloc":["glaring inequity","address inequity","social inequity"],"theme":"society"},{"w":"integration","pos":"noun","def":"the process of becoming a full part of a society or group","defId":"proses menjadi bagian penuh dari suatu masyarakat atau kelompok","ex":"Language classes help the integration of immigrants into their new communities.","exId":"Kelas bahasa membantu integrasi para imigran ke dalam komunitas baru mereka.","colloc":["social integration","economic integration","promote integration"],"theme":"society"},{"w":"intolerance","pos":"noun","def":"An unwillingness to accept beliefs, behaviour, or people that differ from one's own.","defId":"Intoleransi; keengganan menerima keyakinan atau perilaku yang berbeda.","ex":"Religious intolerance has fuelled tensions between the two communities.","exId":"Intoleransi agama telah memicu ketegangan antara kedua komunitas itu.","colloc":["religious intolerance","growing intolerance"],"theme":"society"},{"w":"jurisdiction","pos":"noun","def":"the official power to make legal decisions in a particular area","defId":"kewenangan resmi untuk membuat keputusan hukum di wilayah tertentu","ex":"The crime falls under the jurisdiction of the local courts.","exId":"Kejahatan itu berada di bawah yurisdiksi pengadilan setempat.","colloc":["legal jurisdiction","under the jurisdiction of","outside its jurisdiction"],"theme":"society"},{"w":"legislation","pos":"noun","def":"a law or set of laws made by a government","defId":"sebuah undang-undang atau kumpulan undang-undang yang dibuat oleh pemerintah","ex":"New legislation was passed to protect workers from unfair dismissal.","exId":"Undang-undang baru disahkan untuk melindungi pekerja dari pemutusan hubungan kerja yang tidak adil.","colloc":["pass legislation","new legislation","introduce legislation"],"theme":"society"},{"w":"marginalisation","pos":"noun","def":"The process of treating a person or group as insignificant and pushing them to the edge of society.","defId":"Marginalisasi; proses meminggirkan seseorang atau kelompok dari kehidupan masyarakat.","ex":"The report highlights the ongoing marginalisation of ethnic minorities.","exId":"Laporan itu menyoroti marginalisasi yang terus berlangsung terhadap kelompok minoritas etnis.","colloc":["social marginalisation","economic marginalisation"],"theme":"society"},{"w":"marginalised","pos":"adjective","def":"treated as unimportant and pushed to the edge of society","defId":"diperlakukan sebagai tidak penting dan tersingkir ke pinggiran masyarakat","ex":"Charities work to support marginalised groups who lack access to basic services.","exId":"Lembaga amal berupaya membantu kelompok-kelompok terpinggirkan yang tidak memiliki akses ke layanan dasar.","colloc":["marginalised groups","marginalised communities","socially marginalised"],"theme":"society"},{"w":"melting pot","pos":"noun","def":"a place where many different peoples and cultures mix and blend together","defId":"tempat berbaurnya beragam bangsa dan budaya menjadi satu kesatuan","ex":"The port city has long been a melting pot of languages and traditions.","exId":"Kota pelabuhan itu telah lama menjadi tempat berbaurnya beragam bahasa dan tradisi.","colloc":["a cultural melting pot","melting pot of cultures","become a melting pot"],"theme":"society"},{"w":"migrant","pos":"noun","def":"a person who moves from one place to another, especially to find work or better conditions","defId":"migran; orang yang berpindah dari satu tempat ke tempat lain, terutama untuk mencari kerja atau kehidupan lebih baik","ex":"Seasonal migrants make up a large share of the workforce during the harvest.","exId":"Migran musiman menyumbang sebagian besar tenaga kerja selama masa panen.","colloc":["economic migrant","seasonal migrant","migrant workers"],"theme":"society"},{"w":"migration","pos":"noun","def":"the movement of large numbers of people from one place to another to live","defId":"perpindahan sejumlah besar orang dari satu tempat ke tempat lain untuk menetap","ex":"Economic migration from rural areas to cities continues to grow each year.","exId":"Migrasi ekonomi dari daerah pedesaan ke kota terus meningkat setiap tahun.","colloc":["mass migration","economic migration","migration patterns"],"theme":"society"},{"w":"millennial","pos":"noun","def":"a person born roughly between the early 1980s and the mid-1990s","defId":"milenial; orang yang lahir kira-kira antara awal 1980-an dan pertengahan 1990-an","ex":"Many millennials are delaying home ownership because of soaring prices.","exId":"Banyak milenial menunda kepemilikan rumah karena harga yang melonjak.","colloc":["young millennials","millennial generation","millennials and Gen Z"],"theme":"society"},{"w":"minority","pos":"noun","def":"a small group within a larger group, especially one of a different race or religion","defId":"kelompok kecil di dalam kelompok yang lebih besar, terutama yang berbeda ras atau agama","ex":"The country protects the rights of ethnic minorities through special laws.","exId":"Negara ini melindungi hak-hak kelompok minoritas etnis melalui undang-undang khusus.","colloc":["ethnic minority","minority group","minority rights"],"theme":"society"},{"w":"multicultural","pos":"adjective","def":"including people of many different cultures, races, or religions","defId":"mencakup orang-orang dari berbagai budaya, ras, atau agama yang berbeda","ex":"London is a multicultural city where dozens of languages are spoken.","exId":"London adalah kota multikultural di mana puluhan bahasa dituturkan.","colloc":["multicultural society","multicultural city","multicultural community"],"theme":"society"},{"w":"multiculturalism","pos":"noun","def":"The presence and acceptance of several distinct cultural or ethnic groups within a society.","defId":"Multikulturalisme; keberadaan dan penerimaan berbagai budaya dalam satu masyarakat.","ex":"The city celebrates its multiculturalism with festivals from around the world.","exId":"Kota itu merayakan multikulturalismenya dengan festival dari seluruh dunia.","colloc":["embrace multiculturalism","policy of multiculturalism"],"theme":"society"},{"w":"nativism","pos":"noun","def":"a policy or attitude that favours the interests of native inhabitants over immigrants","defId":"nativisme; kebijakan atau sikap yang mengutamakan kepentingan penduduk asli di atas pendatang","ex":"The rise in nativism fuelled hostility towards recent arrivals.","exId":"Meningkatnya nativisme memicu permusuhan terhadap para pendatang baru.","colloc":["rising nativism","a wave of nativism","nativism and xenophobia"],"theme":"society"},{"w":"naturalisation","pos":"noun","def":"the legal process by which a foreign resident becomes a citizen of a country","defId":"naturalisasi; proses hukum seorang penduduk asing menjadi warga negara","ex":"After five years of residence, she applied for naturalisation.","exId":"Setelah lima tahun bermukim, dia mengajukan naturalisasi.","colloc":["apply for naturalisation","naturalisation process","naturalisation ceremony"],"theme":"society"},{"w":"newcomer","pos":"noun","def":"a person who has recently arrived in a place, group or activity","defId":"pendatang baru; orang yang baru saja tiba di suatu tempat, kelompok, atau kegiatan","ex":"The neighbourhood association runs a welcome scheme to help newcomers settle in.","exId":"Perkumpulan lingkungan menjalankan program sambutan untuk membantu pendatang baru menyesuaikan diri.","colloc":["a relative newcomer","welcome newcomers","newcomer to the area"],"theme":"society"},{"w":"nonconformist","pos":"noun","def":"a person who does not follow generally accepted customs, beliefs or behaviour","defId":"nonkonformis; orang yang tidak mengikuti adat, keyakinan, atau perilaku yang diterima umum","ex":"As a nonconformist, he refused to follow the conventions expected of him.","exId":"Sebagai seorang nonkonformis, dia menolak mengikuti konvensi yang diharapkan darinya.","colloc":["a lifelong nonconformist","social nonconformist","nonconformist views"],"theme":"society"},{"w":"norm","pos":"noun","def":"a standard of behaviour that is normal or expected in a society","defId":"standar perilaku yang dianggap normal atau diharapkan dalam suatu masyarakat","ex":"Social norms about family life vary widely from one culture to another.","exId":"Norma sosial tentang kehidupan keluarga sangat bervariasi dari satu budaya ke budaya lain.","colloc":["social norms","cultural norms","accepted norm"],"theme":"society"},{"w":"offence","pos":"noun","def":"an illegal act; a crime","defId":"tindakan melanggar hukum; sebuah kejahatan","ex":"Driving without a licence is a serious offence in most countries.","exId":"Mengemudi tanpa SIM merupakan pelanggaran serius di sebagian besar negara.","colloc":["criminal offence","commit an offence","minor offence"],"theme":"society"},{"w":"offender","pos":"noun","def":"a person who has committed a crime","defId":"orang yang telah melakukan kejahatan","ex":"First-time offenders are often given a lighter sentence.","exId":"Pelanggar hukum untuk pertama kalinya sering kali diberi hukuman yang lebih ringan.","colloc":["first-time offender","young offender","repeat offender"],"theme":"society"},{"w":"ostracise","pos":"verb","def":"To deliberately exclude someone from a group or society.","defId":"Mengucilkan; sengaja menyingkirkan seseorang dari kelompok atau masyarakat.","ex":"Whistle-blowers are often ostracised by their own colleagues.","exId":"Para pelapor pelanggaran sering dikucilkan oleh rekan kerja mereka sendiri.","colloc":["socially ostracise","ostracise a member"],"theme":"society"},{"w":"patriarchy","pos":"noun","def":"A social system in which men hold most of the power and women are largely excluded from it.","defId":"Patriarki; sistem sosial di mana laki-laki memegang sebagian besar kekuasaan.","ex":"Feminist writers have long challenged the structures of patriarchy.","exId":"Para penulis feminis telah lama menantang struktur patriarki.","colloc":["challenge patriarchy","traditional patriarchy"],"theme":"society"},{"w":"peer group","pos":"noun","def":"a set of people of roughly the same age or status who influence one another","defId":"kelompok sebaya; sekumpulan orang seusia atau setingkat yang saling memengaruhi","ex":"Teenagers often adopt the tastes and opinions of their peer group.","exId":"Remaja sering mengadopsi selera dan pendapat kelompok sebaya mereka.","colloc":["immediate peer group","peer group pressure","influence of the peer group"],"theme":"society"},{"w":"petition","pos":"noun","def":"A formal written request, often signed by many people, appealing to authorities to act.","defId":"Petisi; permohonan tertulis resmi yang ditandatangani banyak orang.","ex":"Thousands signed the petition demanding safer roads for children.","exId":"Ribuan orang menandatangani petisi yang menuntut jalan yang lebih aman untuk anak-anak.","colloc":["sign a petition","online petition"],"theme":"society"},{"w":"philanthropist","pos":"noun","def":"A wealthy person who gives money, time, or resources to help others and support good causes.","defId":"Dermawan; orang yang menyumbangkan uang dan waktu untuk membantu orang lain.","ex":"The new hospital wing was funded by a generous philanthropist.","exId":"Sayap rumah sakit yang baru itu didanai oleh seorang dermawan yang murah hati.","colloc":["wealthy philanthropist","generous philanthropist"],"theme":"society"},{"w":"plight","pos":"noun","def":"A difficult, unfortunate, or dangerous situation that someone is in.","defId":"Kesengsaraan; keadaan sulit atau malang yang dialami seseorang.","ex":"The documentary drew attention to the plight of refugees.","exId":"Film dokumenter itu menarik perhatian pada kesengsaraan para pengungsi.","colloc":["desperate plight","highlight the plight of"],"theme":"society"},{"w":"pluralism","pos":"noun","def":"the peaceful coexistence of different social, cultural or religious groups in one society","defId":"pluralisme; hidup berdampingan secara damai berbagai kelompok sosial, budaya, atau agama dalam satu masyarakat","ex":"The country prides itself on a tradition of religious pluralism.","exId":"Negara itu bangga akan tradisi pluralisme agamanya.","colloc":["cultural pluralism","religious pluralism","embrace pluralism"],"theme":"society"},{"w":"populace","pos":"noun","def":"the ordinary people who live in a country or area, considered as a whole","defId":"rakyat; penduduk biasa suatu negara atau wilayah secara keseluruhan","ex":"The reforms were designed to win the support of a sceptical populace.","exId":"Reformasi itu dirancang untuk memenangkan dukungan rakyat yang skeptis.","colloc":["general populace","local populace","inform the populace"],"theme":"society"},{"w":"prejudice","pos":"noun","def":"an unfair opinion about someone formed without knowing them or the facts","defId":"pendapat tidak adil tentang seseorang yang dibentuk tanpa mengenal orang atau faktanya","ex":"Many people still face prejudice because of their religion or skin colour.","exId":"Banyak orang masih menghadapi prasangka karena agama atau warna kulit mereka.","colloc":["racial prejudice","overcome prejudice","face prejudice"],"theme":"society"},{"w":"privilege","pos":"noun","def":"A special right or advantage enjoyed by a particular person or group, often unfairly.","defId":"Hak istimewa; keuntungan khusus yang hanya dimiliki orang atau kelompok tertentu.","ex":"Many people are unaware of the privilege that comes with their background.","exId":"Banyak orang tidak menyadari hak istimewa yang datang dari latar belakang mereka.","colloc":["social privilege","check your privilege"],"theme":"society"},{"w":"proponent","pos":"noun","def":"a person who argues in favour of an idea, cause or course of action","defId":"pendukung; orang yang berpendapat mendukung suatu gagasan, tujuan, atau tindakan","ex":"She is a leading proponent of affordable housing for low-income families.","exId":"Dia adalah pendukung utama perumahan terjangkau bagi keluarga berpenghasilan rendah.","colloc":["a leading proponent","vocal proponent","proponent of reform"],"theme":"society"},{"w":"prosecution","pos":"noun","def":"the process of officially accusing someone of a crime in a court","defId":"proses menuntut seseorang secara resmi atas suatu kejahatan di pengadilan","ex":"The prosecution presented strong evidence against the defendant.","exId":"Pihak penuntut menghadirkan bukti kuat terhadap terdakwa.","colloc":["face prosecution","criminal prosecution","the prosecution case"],"theme":"society"},{"w":"public interest","pos":"noun","def":"the welfare or well-being of the general public","defId":"kepentingan umum; kesejahteraan atau kebaikan masyarakat luas","ex":"The journalist argued that publishing the documents was clearly in the public interest.","exId":"Jurnalis itu berpendapat bahwa menerbitkan dokumen tersebut jelas demi kepentingan umum.","colloc":["in the public interest","serve the public interest","matter of public interest"],"theme":"society"},{"w":"reform","pos":"noun","def":"a change made to a system or law in order to improve it","defId":"perubahan yang dilakukan terhadap suatu sistem atau undang-undang untuk memperbaikinya","ex":"The government promised major reforms to the education system.","exId":"Pemerintah menjanjikan reformasi besar terhadap sistem pendidikan.","colloc":["social reform","legal reform","introduce reforms"],"theme":"society"},{"w":"safety net","pos":"noun","def":"A system of support, especially provided by the state, that protects people from hardship.","defId":"Jaring pengaman; sistem dukungan yang melindungi orang dari kesulitan.","ex":"Welfare benefits act as a safety net for those who lose their jobs.","exId":"Tunjangan kesejahteraan berfungsi sebagai jaring pengaman bagi mereka yang kehilangan pekerjaan.","colloc":["social safety net","provide a safety net"],"theme":"society"},{"w":"sanction","pos":"noun","def":"an official punishment or action taken against a country or person that breaks a law or rule","defId":"hukuman atau tindakan resmi yang dikenakan terhadap negara atau orang yang melanggar hukum atau aturan","ex":"The international community imposed sanctions on the country for breaking the agreement.","exId":"Komunitas internasional menjatuhkan sanksi terhadap negara itu karena melanggar perjanjian.","colloc":["impose sanctions","economic sanctions","lift sanctions"],"theme":"society"},{"w":"secular","pos":"adjective","def":"not connected with religion or religious matters","defId":"tidak berkaitan dengan agama atau hal-hal keagamaan","ex":"France is a secular state where religion is kept separate from government.","exId":"Prancis adalah negara sekuler di mana agama dipisahkan dari pemerintahan.","colloc":["secular state","secular society","secular education"],"theme":"society"},{"w":"segregation","pos":"noun","def":"the practice of keeping groups of people apart, especially because of race","defId":"praktik memisahkan kelompok-kelompok orang, terutama karena ras","ex":"Racial segregation in schools was finally made illegal.","exId":"Segregasi rasial di sekolah akhirnya dinyatakan ilegal.","colloc":["racial segregation","end segregation","social segregation"],"theme":"society"},{"w":"settler","pos":"noun","def":"a person who moves with others to live in a new region or country","defId":"pemukim; orang yang pindah bersama orang lain untuk menetap di wilayah atau negara baru","ex":"Early settlers cleared the forest and built the first permanent dwellings along the river.","exId":"Para pemukim awal membuka hutan dan mendirikan tempat tinggal permanen pertama di sepanjang sungai.","colloc":["early settlers","new settlers","settler community"],"theme":"society"},{"w":"social contract","pos":"noun","def":"the implicit agreement among people to cooperate for mutual social benefit","defId":"kontrak sosial; kesepakatan tersirat antarwarga untuk bekerja sama demi manfaat bersama","ex":"Critics argue that rising inequality has frayed the social contract.","exId":"Para pengkritik berpendapat bahwa ketimpangan yang meningkat telah merenggangkan kontrak sosial.","colloc":["break the social contract","a new social contract","the social contract between citizens and state"],"theme":"society"},{"w":"social mobility","pos":"noun","def":"The ability of individuals or groups to move up or down between social and economic classes.","defId":"Mobilitas sosial; kemampuan seseorang untuk berpindah antar kelas sosial atau ekonomi.","ex":"Access to good education is often seen as the key to greater social mobility.","exId":"Akses terhadap pendidikan yang baik sering dianggap sebagai kunci mobilitas sosial yang lebih besar.","colloc":["upward social mobility","improve social mobility"],"theme":"society"},{"w":"social norm","pos":"noun","def":"An unwritten rule that defines acceptable and expected behaviour within a society or group.","defId":"Norma sosial; aturan tak tertulis tentang perilaku yang dapat diterima dalam masyarakat.","ex":"Shaking hands is a social norm in many business cultures.","exId":"Berjabat tangan adalah norma sosial dalam banyak budaya bisnis.","colloc":["challenge a social norm","prevailing social norms"],"theme":"society"},{"w":"solidarity","pos":"noun","def":"support and unity among a group of people who share the same aims or interests","defId":"dukungan dan persatuan di antara sekelompok orang yang memiliki tujuan atau kepentingan yang sama","ex":"Workers went on strike in solidarity with their colleagues who had been dismissed.","exId":"Para pekerja melakukan pemogokan sebagai bentuk solidaritas dengan rekan-rekan mereka yang dipecat.","colloc":["show solidarity","in solidarity with","sense of solidarity"],"theme":"society"},{"w":"stereotype","pos":"noun","def":"a fixed and often unfair idea about what a type of person is like","defId":"gagasan yang tetap dan sering kali tidak adil tentang seperti apa suatu jenis orang","ex":"The film challenges common stereotypes about immigrants.","exId":"Film itu menantang stereotip umum tentang para imigran.","colloc":["gender stereotype","negative stereotype","reinforce a stereotype"],"theme":"society"},{"w":"stigma","pos":"noun","def":"A strong sense of social disapproval attached to a particular circumstance, quality, or person.","defId":"Stigma; perasaan ketidaksetujuan sosial yang kuat terhadap sesuatu atau seseorang.","ex":"There is still a stigma surrounding those who claim state benefits.","exId":"Masih ada stigma yang melekat pada mereka yang menerima tunjangan negara.","colloc":["social stigma","attach a stigma"],"theme":"society"},{"w":"stratification","pos":"noun","def":"the arrangement of a society into layers or classes with unequal status","defId":"stratifikasi; penyusunan masyarakat ke dalam lapisan atau kelas dengan status tidak setara","ex":"Sociologists study how wealth reinforces social stratification across generations.","exId":"Para sosiolog mempelajari bagaimana kekayaan memperkuat stratifikasi sosial lintas generasi.","colloc":["social stratification","rigid stratification","stratification by class"],"theme":"society"},{"w":"subculture","pos":"noun","def":"A group within a larger society that has its own distinct beliefs, tastes, or way of life.","defId":"Subkultur; kelompok dalam masyarakat luas dengan nilai atau gaya hidup tersendiri.","ex":"The punk subculture rejected the values of mainstream society.","exId":"Subkultur punk menolak nilai-nilai masyarakat arus utama.","colloc":["youth subculture","distinct subculture"],"theme":"society"},{"w":"taboo","pos":"noun","def":"A subject, word, or action that is avoided or forbidden for social or religious reasons.","defId":"Tabu; hal yang dihindari atau dilarang karena alasan sosial atau agama.","ex":"Talking openly about mental illness was once a strict taboo.","exId":"Membicarakan penyakit mental secara terbuka dahulu merupakan tabu yang ketat.","colloc":["cultural taboo","break a taboo"],"theme":"society"},{"w":"tolerance","pos":"noun","def":"the willingness to accept beliefs or behaviour that are different from your own","defId":"kesediaan untuk menerima keyakinan atau perilaku yang berbeda dari milik sendiri","ex":"Schools should teach tolerance of different religions and cultures.","exId":"Sekolah seharusnya mengajarkan toleransi terhadap agama dan budaya yang berbeda.","colloc":["religious tolerance","show tolerance","zero tolerance"],"theme":"society"},{"w":"tribe","pos":"noun","def":"a social group sharing customs, language and often a common ancestry","defId":"suku; kelompok sosial dengan adat, bahasa, dan sering keturunan yang sama","ex":"Several nomadic tribes have grazed their herds across these plains for centuries.","exId":"Beberapa suku nomaden telah menggembalakan ternak mereka di dataran ini selama berabad-abad.","colloc":["nomadic tribe","tribal customs","a tribe of hunters"],"theme":"society"},{"w":"underclass","pos":"noun","def":"The lowest social group, typically consisting of poor and socially excluded people.","defId":"Kelas bawah; kelompok sosial paling rendah yang biasanya miskin dan terpinggirkan.","ex":"Long-term unemployment has trapped many families in a permanent underclass.","exId":"Pengangguran jangka panjang telah menjebak banyak keluarga dalam kelas bawah yang permanen.","colloc":["permanent underclass","urban underclass"],"theme":"society"},{"w":"underrepresented","pos":"adjective","def":"Present in a group, institution, or field in smaller numbers than would be fair or expected.","defId":"Kurang terwakili; hadir dalam jumlah lebih kecil daripada yang seharusnya.","ex":"Women remain underrepresented in senior political positions.","exId":"Perempuan masih kurang terwakili dalam posisi politik senior.","colloc":["underrepresented groups","underrepresented in"],"theme":"society"},{"w":"undocumented","pos":"adjective","def":"living or working in a country without official legal permission or papers","defId":"tanpa dokumen resmi; tinggal atau bekerja di suatu negara tanpa izin hukum resmi","ex":"Undocumented workers are especially vulnerable to exploitation by employers.","exId":"Pekerja tanpa dokumen resmi sangat rentan terhadap eksploitasi oleh pemberi kerja.","colloc":["undocumented migrants","undocumented workers","undocumented immigrant"],"theme":"society"},{"w":"uplift","pos":"verb","def":"to raise the moral, social or economic condition of a group of people","defId":"mengangkat; memperbaiki kondisi moral, sosial, atau ekonomi suatu kelompok","ex":"The charity aims to uplift impoverished communities through vocational training.","exId":"Lembaga amal itu bertujuan mengangkat komunitas miskin melalui pelatihan kejuruan.","colloc":["uplift the poor","socially uplift","uplift a community"],"theme":"society"},{"w":"urbanisation","pos":"noun","def":"the process by which more people move to and live in cities","defId":"proses ketika semakin banyak orang pindah dan tinggal di kota","ex":"Rapid urbanisation has put pressure on housing and public transport in big cities.","exId":"Urbanisasi yang cepat telah memberi tekanan pada perumahan dan transportasi umum di kota-kota besar.","colloc":["rapid urbanisation","urbanisation process","increasing urbanisation"],"theme":"society"},{"w":"verdict","pos":"noun","def":"the official decision made by a jury or judge in a court of law","defId":"keputusan resmi yang dibuat oleh juri atau hakim di pengadilan","ex":"The jury reached a verdict of not guilty after three days.","exId":"Juri mencapai putusan tidak bersalah setelah tiga hari.","colloc":["reach a verdict","guilty verdict","return a verdict"],"theme":"society"},{"w":"volunteering","pos":"noun","def":"The activity of giving your time freely to help others or a cause without being paid.","defId":"Kegiatan sukarela; memberikan waktu secara cuma-cuma untuk membantu orang lain tanpa dibayar.","ex":"Volunteering at the local shelter gave her a strong sense of purpose.","exId":"Menjadi sukarelawan di penampungan setempat memberinya rasa tujuan yang kuat.","colloc":["community volunteering","volunteering opportunities"],"theme":"society"},{"w":"wealth gap","pos":"noun","def":"The difference in wealth between the richest and poorest members of a society.","defId":"Kesenjangan kekayaan; perbedaan kekayaan antara yang terkaya dan termiskin.","ex":"The wealth gap between the richest and poorest has grown sharply.","exId":"Kesenjangan kekayaan antara yang terkaya dan termiskin telah melebar tajam.","colloc":["widening wealth gap","close the wealth gap"],"theme":"society"},{"w":"welfare","pos":"noun","def":"practical or financial help given by the government to people in need","defId":"bantuan praktis atau keuangan yang diberikan pemerintah kepada orang-orang yang membutuhkan","ex":"Families on low incomes can apply for welfare benefits from the state.","exId":"Keluarga berpenghasilan rendah dapat mengajukan tunjangan kesejahteraan dari negara.","colloc":["welfare state","welfare benefits","social welfare"],"theme":"society"},{"w":"xenophobia","pos":"noun","def":"A strong dislike or fear of people from other countries or of foreigners.","defId":"Xenofobia; ketakutan atau kebencian terhadap orang dari negara lain.","ex":"The rise in xenophobia has made many immigrants feel unwelcome.","exId":"Meningkatnya xenofobia membuat banyak imigran merasa tidak diterima.","colloc":["rising xenophobia","fuel xenophobia"],"theme":"society"}];
